    Ltac open_memI MI :=
      let MI' := fresh "MI'" in pose proof MI as MI';
      destruct MI' as (HP & AUX & [ev ERR] & INV & BS & IDLE & ST & CHN & IN & PA & FR & SZ & [buf BUF] & HIc & TC & XP).
    Ltac prep :=
      pose proof ctx_facts as (X1 & [X2 X2'] & X3 & X4 & X5 & X6 & X7 & X8 & X9 & X10 & X11 & TP & FRM & EHS); pose proof USPW as U;
      pose proof (bv_unsigned_in_range _ sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
      pose proof (bv_unsigned_in_range _ a0) as RA0; unfold bv_modulus in RA0; cbn in RA0; hcb.
    (* [comment removed for export] *)
    Ltac segW := unfold segW_ok; repeat (apply Forall_cons; [cbn [fst snd]; unfold pa, ta in *; lia|]); apply Forall_nil.
    Ltac dj := cbn [disjoint_from fst snd]; unfold pa, ta in *; lia.
    (* [comment removed for export] *)
    Ltac rebuild_memI MI BUF :=
      eapply memI_seg;
      [ exact MI | eassumption | eassumption | eassumption | eassumption | segW
      | unfold pframe; eassumption | unfold psize; eassumption | eassumption | eassumption
      | first [ eapply buf_keep; [exact BUF| eassumption| eassumption| dj]
